        JISREM.CLEANUP_CASE_QUEUE
    SET
        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = '3877d7ea-e37a-4442-b6b0-4f5aabf069b8'
        AND charge_id = 1208451;
   
    RETURN;
END IF;

END IF;

